#include <stdio.h>

typedef struct
{
    int water_ml;
    int milk_ml;
    int beans_g;
    int paper_cups;
} Stock;

Stock stock_after_water_use(Stock stock, int amount_ml)
{
    if (amount_ml >= 0 && amount_ml <= stock.water_ml)
    {
        stock.water_ml -= amount_ml;
    }
    return stock;
}

int main(void)
{
    Stock stock = {500, 200, 40, 3};
    Stock preview = stock_after_water_use(stock, 100);
    printf("%d\n", stock.water_ml);
    printf("%d\n", preview.water_ml);
    stock = stock_after_water_use(stock, 50);
    printf("%d\n", stock.water_ml);
    return 0;
}
